import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Libraries","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/libraries.md","filePath":"ecosystem/libraries.md"}`),a={name:`ecosystem/libraries.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="libraries" tabindex="-1">Libraries <a class="header-anchor" href="#libraries" aria-label="Permalink to “Libraries”">​</a></h1><p><code>lib-*</code> is the largest family in the ecosystem — 130+ repositories of reusable Handl code. The organizing rule is the <strong>port/impl split</strong>:</p><ul><li>A <strong>port</strong> (<code>lib-&lt;name&gt;</code>) is a contract — <code>.hnl</code> signatures, axioms, and laws every backend must satisfy. Ports are pure data + arrow declarations; they never pick a runtime.</li><li>An <strong>impl</strong> (<code>lib-&lt;name&gt;-&lt;backend&gt;</code>) satisfies the contract for one backend: <code>-c</code> over the C FFI, <code>-js</code> over the JS interop surface, <code>-handl</code> as a pure-<code>.hnl</code> implementation, <code>-stub</code> as a deterministic fallback.</li></ul><p>One package per repo, <code>.hnl</code> sources only — Rust appears solely as const-only <code>*_HNL</code> exporter crates that embed the sources. Each repo carries a <code>pkg.hnl</code> manifest declaring <code>{ deps, modules }</code>; dep keys map to <code>handl-lang/lib-&lt;dep&gt;</code> git deps.</p><h2 id="language-and-runtime-internals" tabindex="-1">Language and runtime internals <a class="header-anchor" href="#language-and-runtime-internals" aria-label="Permalink to “Language and runtime internals”">​</a></h2><p>The substrate libraries the host and plugins embed:</p><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-loader" target="_blank" rel="noreferrer">lib-loader</a></td><td>The pure-handl module loader</td></tr><tr><td><a href="https://github.com/handl-lang/lib-desugar" target="_blank" rel="noreferrer">lib-desugar</a></td><td>The <code>desugar</code> transform pass source</td></tr><tr><td><a href="https://github.com/handl-lang/lib-tag" target="_blank" rel="noreferrer">lib-tag</a></td><td>Tagged-value helpers</td></tr><tr><td><a href="https://github.com/handl-lang/lib-kernel-ir" target="_blank" rel="noreferrer">lib-kernel-ir</a></td><td>The kernel IR as data — 21 ops with signatures, grades, costs, torch denotations</td></tr><tr><td><a href="https://github.com/handl-lang/lib-types" target="_blank" rel="noreferrer">lib-types</a></td><td>FFI type-alias declarations shared by codegen bindings</td></tr><tr><td><a href="https://github.com/handl-lang/lib-ffi" target="_blank" rel="noreferrer">lib-ffi</a></td><td>FFI decls — <code>Errno</code>, call surface</td></tr><tr><td><a href="https://github.com/handl-lang/lib-lang-lex" target="_blank" rel="noreferrer">lib-lang-lex</a> · <a href="https://github.com/handl-lang/lib-lang-parse" target="_blank" rel="noreferrer">lib-lang-parse</a> · <a href="https://github.com/handl-lang/lib-lang-typecheck" target="_blank" rel="noreferrer">lib-lang-typecheck</a> · <a href="https://github.com/handl-lang/lib-lang-eval" target="_blank" rel="noreferrer">lib-lang-eval</a> · <a href="https://github.com/handl-lang/lib-lang-compile" target="_blank" rel="noreferrer">lib-lang-compile</a> · <a href="https://github.com/handl-lang/lib-lang-run-compiled" target="_blank" rel="noreferrer">lib-lang-run-compiled</a></td><td>The <code>lex</code>/<code>parse</code>/<code>typecheck</code>/<code>eval</code>/<code>compile</code>/<code>run_compiled</code> meta functions as composable <code>plugin-lib-*</code> leaves</td></tr><tr><td><a href="https://github.com/handl-lang/lib-js" target="_blank" rel="noreferrer">lib-js</a></td><td>JavaScript interop surface — <code>JS</code> grade, typed call/invoke/await arrows</td></tr><tr><td><a href="https://github.com/handl-lang/lib-utils" target="_blank" rel="noreferrer">lib-utils</a></td><td>Aggregate capability surface (<code>bool</code>, <code>math</code>, <code>str</code> modules)</td></tr></tbody></table><h2 id="core-values-and-combinators" tabindex="-1">Core values and combinators <a class="header-anchor" href="#core-values-and-combinators" aria-label="Permalink to “Core values and combinators”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-option" target="_blank" rel="noreferrer">lib-option</a> · <a href="https://github.com/handl-lang/lib-result" target="_blank" rel="noreferrer">lib-result</a></td><td><code>Option</code> / <code>Result</code> types</td></tr><tr><td><a href="https://github.com/handl-lang/lib-cmp" target="_blank" rel="noreferrer">lib-cmp</a></td><td>Comparison predicates — eq/lt/gt/clamp/min/max/compare</td></tr><tr><td><a href="https://github.com/handl-lang/lib-mood" target="_blank" rel="noreferrer">lib-mood</a></td><td>Mood (mode-of-data) operations</td></tr><tr><td><a href="https://github.com/handl-lang/lib-obj" target="_blank" rel="noreferrer">lib-obj</a></td><td>Record introspection — keys/values/entries</td></tr><tr><td><a href="https://github.com/handl-lang/lib-type" target="_blank" rel="noreferrer">lib-type</a> · <a href="https://github.com/handl-lang/lib-type-handl" target="_blank" rel="noreferrer">lib-type-handl</a></td><td>The <code>type</code> capability surface + <code>dependent</code> indexed families; pure-handl predicates/kind guards</td></tr><tr><td><a href="https://github.com/handl-lang/lib-error" target="_blank" rel="noreferrer">lib-error</a></td><td><code>error.raise</code> primitive</td></tr><tr><td><a href="https://github.com/handl-lang/lib-event" target="_blank" rel="noreferrer">lib-event</a></td><td>User-space event emission + listener registration</td></tr><tr><td><a href="https://github.com/handl-lang/lib-pred" target="_blank" rel="noreferrer">lib-pred</a> · <a href="https://github.com/handl-lang/lib-comb" target="_blank" rel="noreferrer">lib-comb</a></td><td>Predicate/filter and combinator libraries</td></tr><tr><td><a href="https://github.com/handl-lang/lib-query" target="_blank" rel="noreferrer">lib-query</a> · <a href="https://github.com/handl-lang/lib-command" target="_blank" rel="noreferrer">lib-command</a></td><td>User-space query/command registration and invocation algebras</td></tr><tr><td><a href="https://github.com/handl-lang/lib-mri" target="_blank" rel="noreferrer">lib-mri</a></td><td>Minimal argv parser (npm <code>mri</code> semantics, pure handl)</td></tr><tr><td><a href="https://github.com/handl-lang/lib-dedent" target="_blank" rel="noreferrer">lib-dedent</a></td><td>Multi-line text dedenting</td></tr><tr><td><a href="https://github.com/handl-lang/lib-encoding" target="_blank" rel="noreferrer">lib-encoding</a></td><td>Codec port — <code>Encoder</code>/<code>Decoder</code>/<code>Encoding</code> traits</td></tr><tr><td><a href="https://github.com/handl-lang/lib-base64" target="_blank" rel="noreferrer">lib-base64</a> · <a href="https://github.com/handl-lang/lib-hex" target="_blank" rel="noreferrer">lib-hex</a></td><td>Base64 / hex codecs over <code>lib-encoding</code></td></tr><tr><td><a href="https://github.com/handl-lang/lib-bytes" target="_blank" rel="noreferrer">lib-bytes</a></td><td>Byte-buffer primitives for the <code>Bytes</code> scalar</td></tr><tr><td><a href="https://github.com/handl-lang/lib-arrow-iter" target="_blank" rel="noreferrer">lib-arrow-iter</a></td><td>Arrow iteration over sequences</td></tr><tr><td><a href="https://github.com/handl-lang/lib-perlin" target="_blank" rel="noreferrer">lib-perlin</a> · <a href="https://github.com/handl-lang/lib-simplex" target="_blank" rel="noreferrer">lib-simplex</a></td><td>Perlin / simplex noise</td></tr><tr><td><a href="https://github.com/handl-lang/lib-stats" target="_blank" rel="noreferrer">lib-stats</a></td><td><code>sum</code>/<code>avg</code>/<code>median</code>/<code>stddev</code> over collections</td></tr><tr><td><a href="https://github.com/handl-lang/lib-transform" target="_blank" rel="noreferrer">lib-transform</a></td><td>Transform utilities</td></tr><tr><td><a href="https://github.com/handl-lang/lib-collections" target="_blank" rel="noreferrer">lib-collections</a></td><td><code>vec</code>/<code>list</code>/<code>queue</code>/<code>stack</code>/<code>deque</code>/<code>hash_map</code>/<code>hash_set</code>/<code>array</code>, shipped as sources</td></tr><tr><td><a href="https://github.com/handl-lang/lib-crypto" target="_blank" rel="noreferrer">lib-crypto</a></td><td><code>sha1</code>/<code>sha256</code>/<code>md5</code> as pure-<code>.hnl</code> arrows</td></tr><tr><td><a href="https://github.com/handl-lang/lib-archive" target="_blank" rel="noreferrer">lib-archive</a> · <a href="https://github.com/handl-lang/lib-tar" target="_blank" rel="noreferrer">lib-tar</a></td><td>Archive reading / tar</td></tr><tr><td><a href="https://github.com/handl-lang/lib-kv" target="_blank" rel="noreferrer">lib-kv</a> · <a href="https://github.com/handl-lang/lib-kv-hashmap" target="_blank" rel="noreferrer">lib-kv-hashmap</a> · <a href="https://github.com/handl-lang/lib-kv-map" target="_blank" rel="noreferrer">lib-kv-map</a></td><td>Key-value store trait + <code>HashMap</code> backend + pure-functional map</td></tr><tr><td><a href="https://github.com/handl-lang/lib-mock" target="_blank" rel="noreferrer">lib-mock</a> · <a href="https://github.com/handl-lang/lib-test" target="_blank" rel="noreferrer">lib-test</a></td><td>Spies/stubs/mocks; assert/property/fuzz/snapshot test framework</td></tr><tr><td><a href="https://github.com/handl-lang/lib-hello" target="_blank" rel="noreferrer">lib-hello</a></td><td>The <code>greet</code> arrow — canonical first package</td></tr></tbody></table><h2 id="text-locale-and-time" tabindex="-1">Text, locale, and time <a class="header-anchor" href="#text-locale-and-time" aria-label="Permalink to “Text, locale, and time”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-str" target="_blank" rel="noreferrer">lib-str</a></td><td><code>str</code> port contract — axioms every backend must satisfy</td></tr><tr><td><a href="https://github.com/handl-lang/lib-str-handl" target="_blank" rel="noreferrer">lib-str-handl</a> · <a href="https://github.com/handl-lang/lib-str-c" target="_blank" rel="noreferrer">lib-str-c</a> · <a href="https://github.com/handl-lang/lib-str-js" target="_blank" rel="noreferrer">lib-str-js</a></td><td>Pure-handl / C-ICU / JavaScript backends</td></tr><tr><td><a href="https://github.com/handl-lang/lib-char" target="_blank" rel="noreferrer">lib-char</a> · <a href="https://github.com/handl-lang/lib-char-native" target="_blank" rel="noreferrer">lib-char-native</a></td><td>Character axioms contract; native <code>std::char</code> backend</td></tr><tr><td><a href="https://github.com/handl-lang/lib-unicode" target="_blank" rel="noreferrer">lib-unicode</a> · <a href="https://github.com/handl-lang/lib-unicode-c" target="_blank" rel="noreferrer">lib-unicode-c</a></td><td>Unicode port + backend</td></tr><tr><td><a href="https://github.com/handl-lang/lib-intl" target="_blank" rel="noreferrer">lib-intl</a> · <a href="https://github.com/handl-lang/lib-intl-c" target="_blank" rel="noreferrer">lib-intl-c</a></td><td>Intl port; ICU4C backend over codegen bindings</td></tr><tr><td><a href="https://github.com/handl-lang/lib-datetime" target="_blank" rel="noreferrer">lib-datetime</a></td><td>Date/time port</td></tr></tbody></table><h2 id="numbers-and-noise" tabindex="-1">Numbers and noise <a class="header-anchor" href="#numbers-and-noise" aria-label="Permalink to “Numbers and noise”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-math" target="_blank" rel="noreferrer">lib-math</a></td><td>Math surface contracts</td></tr><tr><td><a href="https://github.com/handl-lang/lib-math-handl" target="_blank" rel="noreferrer">lib-math-handl</a> · <a href="https://github.com/handl-lang/lib-math-c" target="_blank" rel="noreferrer">lib-math-c</a> · <a href="https://github.com/handl-lang/lib-math-js" target="_blank" rel="noreferrer">lib-math-js</a></td><td>Pure-handl / native / JS backends</td></tr><tr><td><a href="https://github.com/handl-lang/lib-tensor" target="_blank" rel="noreferrer">lib-tensor</a> · <a href="https://github.com/handl-lang/lib-tensor-native" target="_blank" rel="noreferrer">lib-tensor-native</a></td><td><code>.hnl</code> tensor-op spec (transparent) ↔ native <code>f64</code> n-d array backend (opaque atoms)</td></tr><tr><td><a href="https://github.com/handl-lang/lib-noise" target="_blank" rel="noreferrer">lib-noise</a></td><td>Noise port types</td></tr><tr><td><a href="https://github.com/handl-lang/lib-noise-handl" target="_blank" rel="noreferrer">lib-noise-handl</a> · <a href="https://github.com/handl-lang/lib-noise-c" target="_blank" rel="noreferrer">lib-noise-c</a> · <a href="https://github.com/handl-lang/lib-noise-stub" target="_blank" rel="noreferrer">lib-noise-stub</a></td><td>Pure-handl / C / stub backends</td></tr></tbody></table><h2 id="serialization-and-formats" tabindex="-1">Serialization and formats <a class="header-anchor" href="#serialization-and-formats" aria-label="Permalink to “Serialization and formats”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-serialize" target="_blank" rel="noreferrer">lib-serialize</a></td><td>Format-agnostic <code>Serializer</code>/<code>Encoder</code>/<code>Decoder</code> port</td></tr><tr><td><a href="https://github.com/handl-lang/lib-json" target="_blank" rel="noreferrer">lib-json</a></td><td>JSON codec + <code>json.parse</code>/<code>stringify</code> over <code>lib-serialize</code> traits</td></tr><tr><td><a href="https://github.com/handl-lang/lib-json-handl" target="_blank" rel="noreferrer">lib-json-handl</a> · <a href="https://github.com/handl-lang/lib-json-c" target="_blank" rel="noreferrer">lib-json-c</a> · <a href="https://github.com/handl-lang/lib-json-js" target="_blank" rel="noreferrer">lib-json-js</a></td><td>Pure-handl / C-FFI / JS backends</td></tr><tr><td><a href="https://github.com/handl-lang/lib-serialize-toml-c" target="_blank" rel="noreferrer">lib-serialize-toml-c</a> · <a href="https://github.com/handl-lang/lib-serialize-yaml-c" target="_blank" rel="noreferrer">lib-serialize-yaml-c</a></td><td>Native TOML / YAML serializer backends</td></tr><tr><td><a href="https://github.com/handl-lang/lib-url-rfc" target="_blank" rel="noreferrer">lib-url-rfc</a> · <a href="https://github.com/handl-lang/lib-url-whatwg" target="_blank" rel="noreferrer">lib-url-whatwg</a></td><td>URL parsers for the <code>parse</code> port — RFC and WHATWG dialects</td></tr></tbody></table><h2 id="system-process-and-cli" tabindex="-1">System, process, and CLI <a class="header-anchor" href="#system-process-and-cli" aria-label="Permalink to “System, process, and CLI”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-posix" target="_blank" rel="noreferrer">lib-posix</a></td><td>POSIX.1-2017 contract — fd ops, path, env, time, fs</td></tr><tr><td><a href="https://github.com/handl-lang/lib-posix-c" target="_blank" rel="noreferrer">lib-posix-c</a> · <a href="https://github.com/handl-lang/lib-posix-stub" target="_blank" rel="noreferrer">lib-posix-stub</a></td><td>C backend / deterministic stub</td></tr><tr><td><a href="https://github.com/handl-lang/lib-stdio" target="_blank" rel="noreferrer">lib-stdio</a></td><td>Standard-stream I/O contract</td></tr><tr><td><a href="https://github.com/handl-lang/lib-stdio-c" target="_blank" rel="noreferrer">lib-stdio-c</a></td><td>libc backend via <code>ffi.call</code></td></tr><tr><td><a href="https://github.com/handl-lang/lib-proc" target="_blank" rel="noreferrer">lib-proc</a></td><td>Process identity contract — <code>argv</code>/<code>exit</code>/<code>pid</code></td></tr><tr><td><a href="https://github.com/handl-lang/lib-cli" target="_blank" rel="noreferrer">lib-cli</a></td><td>Child-process spawn contract + <code>cli-c</code> libc backend</td></tr><tr><td><a href="https://github.com/handl-lang/lib-cli-router" target="_blank" rel="noreferrer">lib-cli-router</a></td><td>CLI ergonomics — compiler + segment trie + <code>{out,state}</code> pipeline</td></tr><tr><td><a href="https://github.com/handl-lang/lib-command" target="_blank" rel="noreferrer">lib-command</a></td><td>Command registration/invocation algebra (see Core values)</td></tr><tr><td><a href="https://github.com/handl-lang/lib-gh" target="_blank" rel="noreferrer">lib-gh</a></td><td>Generated handl SDK for the GitHub CLI (<code>gh.clispec.yaml</code> is the source of truth)</td></tr><tr><td><a href="https://github.com/handl-lang/lib-cli-gen" target="_blank" rel="noreferrer">lib-cli-gen</a></td><td>Multi-tool generated SDKs — <code>git</code>, <code>docker</code>, <code>ffmpeg</code>, <code>kubectl</code>, <code>aws</code></td></tr><tr><td><a href="https://github.com/handl-lang/lib-curl" target="_blank" rel="noreferrer">lib-curl</a> · <a href="https://github.com/handl-lang/lib-libc" target="_blank" rel="noreferrer">lib-libc</a> · <a href="https://github.com/handl-lang/lib-libz" target="_blank" rel="noreferrer">lib-libz</a></td><td>Codegen-generated FFI bindings (ports + <code>c-linux-x86_64</code> adapters)</td></tr></tbody></table><h2 id="networking-and-serving" tabindex="-1">Networking and serving <a class="header-anchor" href="#networking-and-serving" aria-label="Permalink to “Networking and serving”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-fetch" target="_blank" rel="noreferrer">lib-fetch</a></td><td><code>fetch</code> port — WinterCG-style request/response</td></tr><tr><td><a href="https://github.com/handl-lang/lib-fetch-c" target="_blank" rel="noreferrer">lib-fetch-c</a> · <a href="https://github.com/handl-lang/lib-fetch-js" target="_blank" rel="noreferrer">lib-fetch-js</a></td><td>libcurl / WebIDL backends</td></tr><tr><td><a href="https://github.com/handl-lang/lib-ws" target="_blank" rel="noreferrer">lib-ws</a></td><td><code>ws</code> port — RFC 6455 client step-surface</td></tr><tr><td><a href="https://github.com/handl-lang/lib-ws-c" target="_blank" rel="noreferrer">lib-ws-c</a></td><td>libcurl-transport WebSocket client for <code>concurrent-epoll</code></td></tr><tr><td><a href="https://github.com/handl-lang/lib-ws-whatwg-c" target="_blank" rel="noreferrer">lib-ws-whatwg-c</a> · <a href="https://github.com/handl-lang/lib-ws-whatwg-wasm" target="_blank" rel="noreferrer">lib-ws-whatwg-wasm</a></td><td>WHATWG WebSocket surfaces for C / wasm-JS hosts</td></tr><tr><td><a href="https://github.com/handl-lang/lib-ws-frame" target="_blank" rel="noreferrer">lib-ws-frame</a> · <a href="https://github.com/handl-lang/lib-ws-frame-handl" target="_blank" rel="noreferrer">lib-ws-frame-handl</a></td><td>RFC 6455 frame contract + pure-handl codec</td></tr><tr><td><a href="https://github.com/handl-lang/lib-tls" target="_blank" rel="noreferrer">lib-tls</a> · <a href="https://github.com/handl-lang/lib-tls-libssl" target="_blank" rel="noreferrer">lib-tls-libssl</a></td><td>TLS step-surface contract; nonblocking libssl primitives</td></tr><tr><td><a href="https://github.com/handl-lang/lib-serve" target="_blank" rel="noreferrer">lib-serve</a> · <a href="https://github.com/handl-lang/lib-serve-epoll" target="_blank" rel="noreferrer">lib-serve-epoll</a></td><td>HTTP server around a fetch-shaped handler; epoll accept loop</td></tr><tr><td><a href="https://github.com/handl-lang/lib-http-rfc" target="_blank" rel="noreferrer">lib-http-rfc</a></td><td>HTTP/1.1 wire codec in pure handl</td></tr><tr><td><a href="https://github.com/handl-lang/lib-route" target="_blank" rel="noreferrer">lib-route</a></td><td>Transport-agnostic routing + middleware pipeline</td></tr><tr><td><a href="https://github.com/handl-lang/lib-http-router" target="_blank" rel="noreferrer">lib-http-router</a></td><td>HTTP routing layer between <code>serve</code> and handler arrows</td></tr><tr><td><a href="https://github.com/handl-lang/lib-http-middleware" target="_blank" rel="noreferrer">lib-http-middleware</a> · <a href="https://github.com/handl-lang/lib-http-ratelimit" target="_blank" rel="noreferrer">lib-http-ratelimit</a> · <a href="https://github.com/handl-lang/lib-http-static" target="_blank" rel="noreferrer">lib-http-static</a></td><td>Onion middleware, rate limiting, static file serving</td></tr><tr><td><a href="https://github.com/handl-lang/lib-http-openapi" target="_blank" rel="noreferrer">lib-http-openapi</a></td><td>OpenAPI 3.0.x spec generator over handl records</td></tr><tr><td><a href="https://github.com/handl-lang/lib-msg-router" target="_blank" rel="noreferrer">lib-msg-router</a></td><td>Message/event-envelope dispatcher</td></tr><tr><td><a href="https://github.com/handl-lang/lib-ip" target="_blank" rel="noreferrer">lib-ip</a></td><td>IP address, CIDR, socket primitives</td></tr><tr><td><a href="https://github.com/handl-lang/lib-concurrent" target="_blank" rel="noreferrer">lib-concurrent</a></td><td>Cooperative concurrency contract (step-arrow model)</td></tr><tr><td><a href="https://github.com/handl-lang/lib-concurrent-epoll" target="_blank" rel="noreferrer">lib-concurrent-epoll</a> · <a href="https://github.com/handl-lang/lib-concurrent-js" target="_blank" rel="noreferrer">lib-concurrent-js</a></td><td>epoll scheduler / JS isomorphic backend</td></tr><tr><td><a href="https://github.com/handl-lang/lib-otlp" target="_blank" rel="noreferrer">lib-otlp</a></td><td>OpenTelemetry/OTLP module surface</td></tr><tr><td><a href="https://github.com/handl-lang/lib-otlp-c" target="_blank" rel="noreferrer">lib-otlp-c</a> · <a href="https://github.com/handl-lang/lib-otlp-std" target="_blank" rel="noreferrer">lib-otlp-std</a></td><td>Native OTLP exporter / <code>ureq</code>-based HTTP exporter</td></tr></tbody></table><h2 id="compression" tabindex="-1">Compression <a class="header-anchor" href="#compression" aria-label="Permalink to “Compression”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/lib-compress" target="_blank" rel="noreferrer">lib-compress</a></td><td>Compression contract — codec types + backend laws</td></tr><tr><td><a href="https://github.com/handl-lang/lib-compress-gzip-c" target="_blank" rel="noreferrer">lib-compress-gzip-c</a> · <a href="https://github.com/handl-lang/lib-compress-zlib-c" target="_blank" rel="noreferrer">lib-compress-zlib-c</a></td><td>gzip (zlib <code>gz*</code>) / raw-deflate backends over <code>libz</code></td></tr></tbody></table><p>Adding a library follows the same rule as adding a language: declare the contract as a port, ship at least one impl, and let <code>pkg.hnl</code> deps carry the wiring. The <a href="/docs/ecosystem/kits.html">kits</a> curate these into ready-to-use environments.</p>`,22)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};